def transform(grid):
    out = [row[:] for row in grid]
    w = len(grid[0])
    full_rows = {tuple(row) for row in grid if len(set(row)) == 1}
    # A solid-color row identifies the patterned color; fill the remainder of
    # any partial row of that color with 1.
    for r, row in enumerate(grid):
        for color in {v for v in row}:
            if tuple([color] * w) in full_rows and row.count(color) < w:
                # Only contiguous partial bars are extended from their colored end.
                indices = [i for i, v in enumerate(row) if v == color]
                if indices and indices == list(range(min(indices), max(indices)+1)):
                    for c in range(max(indices)+1, w):
                        out[r][c] = 1
    return out
